 using System.ComponentModel;
 using System.Net.Http.Json;
 using System.Text.Json;
 using ModelContextProtocol.Server;

 /// <summary>
 /// MCP tool class wrapping the US National Weather Service REST API.
 /// The MCP SDK instantiates this class per-call, injecting constructor
 /// dependencies from the DI container registered in Program.cs.
 /// </summary>
 public class WeatherTools
 {
     private readonly HttpClient _http;

     // IHttpClientFactory is resolved from DI automatically.
     public WeatherTools(IHttpClientFactory httpClientFactory)
     {
         _http = httpClientFactory.CreateClient("WeatherApi");
     }

     [McpServerTool(Name = "get_alerts"),
      Description("Get active weather alerts for a US state (two-letter code, e.g. CA).")]
     public async Task<string> GetAlerts(
         [Description("Two-letter US state code")] string state)
     {
         var json = await _http.GetFromJsonAsync<JsonDocument>(
             $"/alerts/active?area={state}");

         var features = json?.RootElement.GetProperty("features");
         if (features is null || features.Value.GetArrayLength() == 0)
             return $"No active alerts for {state}.";

         var lines = new List<string>();
         foreach (var feature in features.Value.EnumerateArray())
         {
             var props = feature.GetProperty("properties");
             var headline = props.GetProperty("headline").GetString();
             var severity = props.GetProperty("severity").GetString();
             var description = props.GetProperty("description").GetString();
             lines.Add($"[{severity}] {headline}\n{description}");
         }

         return string.Join("\n---\n", lines);
     }

     [McpServerTool(Name = "get_forecast"),
      Description("Get the weather forecast for a location by latitude and longitude.")]
