             .GetProperty("properties")
             .GetProperty("forecast")
             .GetString();

         if (forecastUrl is null)
             return "Could not resolve forecast URL for that location.";

         // Step 2: fetch the actual forecast.
         var forecastJson = await _http.GetFromJsonAsync<JsonDocument>(forecastUrl);
         var periods = forecastJson?.RootElement
             .GetProperty("properties")
             .GetProperty("periods");

         if (periods is null)
             return "No forecast data available.";

         var lines = new List<string>();
         foreach (var period in periods.Value.EnumerateArray())
